export const STUDENT_GUIDES:Readonly<Record<StudentGuideId,StudentGuide>>=Object.freeze({plans:withActions(plans),tools:withActions(tools),workspace:withActions(workspace),practice:withActions(practice),max:withActions(max),research:withActions(research),coursework:withActions(coursework),academic:withActions(academic),session:withActions(session),exams:withActions(exams),assistant:withActions(assistant)})
