export const STUDENT_GUIDE_IDS=Object.freeze(Object.keys(STUDENT_GUIDES) as StudentGuideId[])
export function isSafeStudentGuideReveal(selector:string):boolean{return /^\.(sdt-tabs|spl-tabs|swb-tabs|mcs-tabs) button:nth-child\([1-5]\)$/.test(selector)}
export function getStudentGuide(id:string):StudentGuide|null{return Object.prototype.hasOwnProperty.call(STUDENT_GUIDES,id)?STUDENT_GUIDES[id as StudentGuideId]:null}
export type StudentGuideControlKind='button'|'link'|'input'|'select'|'textarea'|'checkbox'|'radio'|'range'|'summary'
export function describeStudentGuideAction(guideId:string,label:string,kind:StudentGuideControlKind='button',disabled=false,contextActionId?:string):StudentGuideAction{
 const guide=getStudentGuide(guideId),clean=label.replace(/\s+/g,' ').trim().slice(0,400)
 const action=(contextActionId&&guide?.actions.find(item=>item.id===contextActionId))||guide?.actions.find(item=>new RegExp(item.pattern,'iu').test(clean))
 if(action)return disabled?{...action,tip:`Зараз дія недоступна. Перевір активний тариф, обов’язкові поля або поточний стан. ${action.tip}`}:action
 const title=clean||'Цей елемент'
 const body=kind==='input'||kind==='textarea'?['Поле приймає твої власні дані для поточного інструмента.','Прочитай підпис і приклад. Якщо є окрема кнопка збереження, заповнення поля саме не підтверджує форму.','Навчання показує призначення, не змінюючи введений текст.']:kind==='select'?['Список дозволяє вибрати одне з доступних значень.','Відкрий список, прочитай варіанти та вибери потрібний після виходу з режиму пояснення.','Наслідок вибору залежить від підпису поля: це може бути фільтр, формат чи робочий матеріал.']:kind==='checkbox'||kind==='radio'?['Позначка обирає стан або один доступний варіант.','Перевір підпис: це може бути правильна відповідь, умова або особисте виконання.','У режимі пояснення стан не змінюється.']:kind==='range'?['Повзунок задає числове припущення у видимих межах.','Перевір мінімум, максимум і пояснення поруч перед зміною.','Після виходу з підказок стрілки клавіатури також дозволяють змінити значення.']:kind==='summary'?['Розгортає або згортає пояснення цього запису.','Всередині можуть бути деталі, варіанти, історія або додаткові дії.','Саме розгортання не підтверджує форму й не завершує роботу.']:kind==='link'?['Це посилання на окремий матеріал або сторінку.','Перевір адресу й походження перед переходом.','У режимі пояснення посилання не відкривається.']:['Кнопка має назву, наведену вище. У цьому режимі її дію заблоковано, щоб ти міг спочатку розібратися.','Перевір підпис блоку та стан елемента. Якщо це запис у списку, він може відкривати деталі саме цього запису.','Для виконання спочатку поверни керування. Нічого не буде натиснуто автоматично.']
 return {id:'visible-control',label:title,pattern:'',title:'Для цієї дії ще немає окремої інструкції',body:[`Елемент: «${title}».`,...body],tip:disabled?'Зараз елемент недоступний. Перевір поля форми, активний тариф і поточний стан.':'Тут наведені лише загальні правила. Ми не вигадуємо результат невідомої дії. Скористайся поясненням блоку або звернися до команди.',tone:'plain'}
}
export function studentGuideActionCoverage(guideId:string,controls:readonly {label:string;kind?:StudentGuideControlKind;disabled?:boolean;contextActionId?:string}[]){const unmatched=controls.filter(c=>describeStudentGuideAction(guideId,c.label,c.kind,c.disabled,c.contextActionId).id==='visible-control').map(c=>({label:c.label,kind:c.kind||'button'}));return {total:controls.length,specific:controls.length-unmatched.length,unmatched}}
export function searchStudentGuideActions(guideId:string,query:string):readonly StudentGuideAction[]{const guide=getStudentGuide(guideId);if(!guide)return [];const q=query.trim().toLocaleLowerCase('uk-UA').slice(0,100);return q?guide.actions.filter(a=>[a.label,a.title,...a.body,a.tip].join(' ').toLocaleLowerCase('uk-UA').includes(q)):guide.actions}
export type StudentGuidePreferences={version:1;completed:StudentGuideId[]}
export function parseStudentGuidePreferences(raw:string|null):StudentGuidePreferences{const result:StudentGuidePreferences={version:1,completed:[]};if(!raw||raw.length>3000)return result;try{const value=JSON.parse(raw);if(value?.version!==1||!Array.isArray(value.completed))return result;result.completed=STUDENT_GUIDE_IDS.filter(id=>value.completed.includes(id));return result}catch{return result}}
export function completeStudentGuide(prefs:StudentGuidePreferences,id:string):StudentGuidePreferences{return {version:1,completed:STUDENT_GUIDE_IDS.filter(key=>prefs.completed.includes(key)||key===id)}}
export type StudentGuideRect={left:number;top:number;width:number;height:number}
export function placeStudentGuidePanel(target:StudentGuideRect|null,viewport:{width:number;height:number},panel:{width:number;height:number},gap=16){
 const margin=Math.min(12,Math.max(0,Math.min(viewport.width,viewport.height)/4)),width=Math.max(1,Math.min(panel.width,viewport.width-margin*2)),height=Math.max(1,Math.min(panel.height,viewport.height-margin*2)),limitX=Math.max(margin,viewport.width-width-margin),limitY=Math.max(margin,viewport.height-height-margin)
 const clamp=(v:number,min:number,max:number)=>Math.max(min,Math.min(max,v))
 if(!target)return {left:Math.max(margin,(viewport.width-width)/2),top:Math.max(margin,(viewport.height-height)/2),width,height,side:'center' as const}
 const candidates=[{left:target.left+target.width+gap,top:target.top,side:'right'},{left:target.left-width-gap,top:target.top,side:'left'},{left:target.left,top:target.top+target.height+gap,side:'bottom'},{left:target.left,top:target.top-height-gap,side:'top'}]
 const choices=candidates.map((c,index)=>{const left=clamp(c.left,margin,limitX),top=clamp(c.top,margin,limitY),overlap=Math.max(0,Math.min(left+width,target.left+target.width+8)-Math.max(left,target.left-8))*Math.max(0,Math.min(top+height,target.top+target.height+8)-Math.max(top,target.top-8)),movement=Math.abs(left-c.left)+Math.abs(top-c.top);return {left,top,width,height,side:c.side,score:overlap*100+movement+index/10}}).sort((a,b)=>a.score-b.score)
 const {score:_,...best}=choices[0];return best
}
